import { type } from "arktype";

const skuPattern = /^[A-Z]{2}-\d{4}-[a-z]{3}$/;

export const catalogSchema = type({
  vendorId: "string.uuid",
  skus: type("string[]")
    .narrow((skus, ctx) => {
      const seen = new Set<string>();
      for (let i = 0; i < skus.length; i++) {
        if (seen.has(skus[i])) {
          return ctx.mustBe("unique");
        }
        seen.add(skus[i]);
      }
      return true;
    })
    .narrow((skus, ctx) => {
      if (skus.length < 1 || skus.length > 200) {
        return ctx.mustBe("between 1 and 200 elements");
      }
      return true;
    }),
}).narrow((data, ctx) => {
  const skus = data.skus;
  for (let i = 0; i < skus.length; i++) {
    if (!skuPattern.test(skus[i])) {
      return ctx.mustBe(`matching pattern ${skuPattern.source}`);
    }
  }
  return true;
});

export type Catalog = typeof catalogSchema.infer;

